CREATE TABLE faultline.evidence(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,value jsonb NOT NULL,redaction_status text NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id));
CREATE TABLE faultline.hypotheses(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,value jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id));
CREATE TABLE faultline.analytic_plans(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,value jsonb NOT NULL,plan_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id));
CREATE TABLE faultline.analytic_results(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,revision_id uuid NOT NULL,plan_id uuid NOT NULL,value jsonb NOT NULL,job_id uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id,plan_id) REFERENCES faultline.analytic_plans(workspace_id,case_id,id));
CREATE TABLE faultline.report_drafts(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,value jsonb NOT NULL,binding jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,published_id uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id));
CREATE TABLE faultline.report_versions(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,value jsonb NOT NULL,binding jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,case_id,id),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id));
CREATE TABLE faultline.report_exports(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,report_id uuid NOT NULL,object_key text NOT NULL,format text NOT NULL,manifest jsonb NOT NULL,signature text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id,report_id) REFERENCES faultline.report_versions(workspace_id,case_id,id));
CREATE TABLE faultline.comments(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,actor_id text NOT NULL,text text NOT NULL,evidence_ids jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,tombstone boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id) REFERENCES faultline.cases(workspace_id,id));
CREATE TABLE faultline.followups(id uuid PRIMARY KEY,workspace_id uuid NOT NULL,case_id uuid NOT NULL,actor_id text NOT NULL,revision_id uuid NOT NULL,value jsonb NOT NULL,state text NOT NULL,revision integer NOT NULL DEFAULT 1,result jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,case_id,revision_id) REFERENCES faultline.case_revisions(workspace_id,case_id,id));
DO $scope$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['evidence','hypotheses','analytic_plans','analytic_results','report_drafts','report_versions','report_exports','comments','followups'] LOOP
EXECUTE format('ALTER TABLE faultline.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE faultline.%I FORCE ROW LEVEL SECURITY',t);
EXECUTE format('CREATE POLICY tenant_scope ON faultline.%I USING(workspace_id::text=current_setting(''faultline.workspace_id'',true)) WITH CHECK(workspace_id::text=current_setting(''faultline.workspace_id'',true))',t);
END LOOP;END $scope$;
GRANT SELECT,INSERT ON faultline.evidence,faultline.hypotheses,faultline.analytic_plans,faultline.analytic_results,faultline.report_drafts,faultline.report_versions,faultline.report_exports,faultline.comments,faultline.followups TO faultline_api;
GRANT UPDATE(value,redaction_status,revision) ON faultline.evidence TO faultline_api;
GRANT UPDATE(value,revision) ON faultline.hypotheses TO faultline_api;
GRANT UPDATE(value,revision,published_id) ON faultline.report_drafts TO faultline_api;
GRANT UPDATE(text,revision,tombstone,updated_at) ON faultline.comments TO faultline_api;
GRANT UPDATE(state,revision,result) ON faultline.followups TO faultline_api;
